import { Effect } from "effect";
import { describe, expect, it, vi } from "vitest";

import { createHevyClient } from "./hevy-client.js";
import { HEVY_DEADLINE_EXCEEDED_ERROR_CODE } from "./hevy-http-error.js";
import { getRequestEffectClient } from "./internal.ts";

function json(data: unknown, status = 200, headers: HeadersInit = {}) {
	return new Response(JSON.stringify(data), {
		status,
		headers: { "content-type": "application/json", ...headers },
	});
}

function urlOf(fetchMock: ReturnType<typeof vi.fn>, call = 0): URL {
	const input = fetchMock.mock.calls[call]?.[0] as RequestInfo | URL;
	return new URL(
		input instanceof URL ? input.href : input instanceof Request ? input.url : input,
	);
}

describe("hevy-client bug hunt", () => {
	it("BUG-1: uses the injected sleep option for retry backoff", async () => {
		const sleep = vi.fn(async (_ms: number, _signal?: AbortSignal) => {});
		const fetchMock = vi
			.fn()
			.mockResolvedValueOnce(json({}, 503))
			.mockResolvedValueOnce(json({ ok: true }));
		const client = createHevyClient({
			apiKey: "fake-key",
			fetch: fetchMock,
			maxGetRetries: 1,
			sleep,
		});

		await expect(client.getUserInfo()).resolves.toEqual({ ok: true });
		expect(fetchMock).toHaveBeenCalledTimes(2);
		// HevyClientOptions.sleep is the declared backoff hook.
		expect(sleep).toHaveBeenCalledTimes(1);
	});

	it("BUG-2: a path ID cannot escape its resource via dot segments", async () => {
		const fetchMock = vi.fn(async () => json({ updated: true }));
		const client = createHevyClient({
			apiKey: "fake-key",
			fetch: fetchMock,
			maxGetRetries: 0,
		});

		await client.getWorkout("..");
		await client.updateWorkout(".", {} as never);

		// GET /v1/workouts/{workoutId} must stay under /v1/workouts/<id>.
		expect.soft(urlOf(fetchMock, 0).pathname).toMatch(/^\/v1\/workouts\/[^/]+$/);
		// PUT must not be redirected to the collection path.
		expect.soft(urlOf(fetchMock, 1).pathname).toMatch(/^\/v1\/workouts\/[^/]+$/);
	});

	it("BUG-3: createRoutine does not crash with TypeError on a null 201 body", async () => {
		const fetchMock = vi.fn().mockResolvedValue(
			new Response("null", {
				status: 201,
				headers: { "content-type": "application/json" },
			}),
		);
		const client = createHevyClient({
			apiKey: "fake-key",
			fetch: fetchMock,
			maxGetRetries: 0,
		});

		const outcome = await client
			.createRoutine({ routine: { title: "Fixture", exercises: [] } } as never)
			.then(
				(value) => ({ ok: true as const, value }),
				(error: Error) => ({ ok: false as const, name: error.name }),
			);
		// The create committed; the contract is Routine | undefined, like "{}".
		expect(outcome).toEqual({ ok: true, value: undefined });
	});

	it("BUG-4: never exposes part of the API key in responseError", async () => {
		const apiKey = "REDACTED";
		const message = `${" ".repeat(4_080)}${apiKey}`;
		const fetchMock = vi.fn().mockResolvedValue(json({ error: message }, 400));
		const client = createHevyClient({ apiKey, fetch: fetchMock, maxGetRetries: 0 });

		const error = (await client.getUserInfo().catch((e: unknown) => e)) as {
			responseError?: string;
		};
		expect(error.responseError ?? "").not.toContain("hevykey-ABCDEFGH");
	});

	it("BUG-5: RateLimitError keeps an HTTP-date Retry-After as retryAfterSeconds", async () => {
		const retryAt = new Date(Date.now() + 30_000).toUTCString();
		const fetchMock = vi
			.fn()
			.mockResolvedValue(json({}, 429, { "retry-after": retryAt }));
		const client = createHevyClient({
			apiKey: "fake-key",
			fetch: fetchMock,
			maxGetRetries: 0,
		});

		const error = await Effect.runPromise(
			Effect.flip(getRequestEffectClient(client).getUserInfo()),
		);
		expect(error).toMatchObject({ _tag: "RateLimitError", status: 429 });
		expect((error as { retryAfterSeconds?: number }).retryAfterSeconds).toEqual(
			expect.any(Number),
		);
	});

	it("BUG-6: a NaN deadline does not disable the per-attempt timeout", async () => {
		const fetchMock = vi.fn(
			(_input: RequestInfo | URL, init?: RequestInit) =>
				new Promise<Response>((_resolve, reject) => {
					init?.signal?.addEventListener("abort", () => reject(init.signal?.reason));
				}),
		);
		const client = createHevyClient({
			apiKey: "fake-key",
			fetch: fetchMock,
			maxGetRetries: 0,
		});
		const settled = client
			.getUserInfo({ deadline: Number.NaN, timeoutMs: 20 })
			.then(
				() => "resolved",
				(error: { code?: string }) => error.code,
			);
		const hung = new Promise((resolve) => setTimeout(() => resolve("hung"), 500));
		expect(await Promise.race([settled, hung])).toBe(
			HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
		);
	});
});
